#include <algorithm>
#include <cassert>
#include <cmath>
#include <cstddef>
#include <iostream>
#include <vector>

static std::tuple<std::vector<double>, std::vector<double>, double> empirical_bayes_shrinkage(
    const std::vector<std::vector<double>>& groups) {
    std::vector<double> group_means;
    group_means.reserve(groups.size());
    double sum_means = 0.0;
    for (const auto& g : groups) {
        double gm = 0.0;
        for (double x : g) gm += x;
        gm /= static_cast<double>(g.size());
        group_means.push_back(gm);
        sum_means += gm;
    }
    double grand_mean = sum_means / static_cast<double>(group_means.size());

    std::size_t n_groups = groups.size();
    std::vector<std::size_t> group_sizes;
    group_sizes.reserve(n_groups);
    double sum_sizes = 0.0;
    for (const auto& g : groups) {
        group_sizes.push_back(g.size());
        sum_sizes += static_cast<double>(g.size());
    }
    double avg_group_size = sum_sizes / static_cast<double>(n_groups);

    double var_within = 0.0;
    std::size_t total_obs = 0;
    for (std::size_t i = 0; i < n_groups; ++i) {
        double gm = group_means[i];
        for (double x : groups[i]) {
            var_within += (x - gm) * (x - gm);
        }
        total_obs += groups[i].size();
    }
    if (total_obs > n_groups) {
        var_within /= static_cast<double>(total_obs - n_groups);
    }

    double var_between = 0.0;
    for (double gm : group_means) {
        double d = gm - grand_mean;
        var_between += d * d;
    }
    var_between /= static_cast<double>(n_groups - 1);
    (void)var_between;

    double sampling_var = avg_group_size > 0.0 ? var_within / avg_group_size : 0.0;
    double S = 0.0;
    for (double gm : group_means) {
        double d = gm - grand_mean;
        S += d * d;
    }
    double shrinkage_factor = 0.0;
    if (S > 0.0) {
        shrinkage_factor = std::max(0.0, 1.0 - (static_cast<double>(n_groups) - 3.0) * sampling_var / S);
    }

    std::vector<double> shrunken_means;
    shrunken_means.reserve(n_groups);
    for (double gm : group_means) {
        shrunken_means.push_back(shrinkage_factor * gm + (1.0 - shrinkage_factor) * grand_mean);
    }

    return {shrunken_means, group_means, shrinkage_factor};
}

int main() {
    std::size_t K = TRUE_MEANS.size();

    auto eb_result = empirical_bayes_shrinkage(PY_MAIN_GROUPS);
    const auto& shrunken_means = std::get<0>(eb_result);
    const auto& raw_means = std::get<1>(eb_result);
    double shrinkage = std::get<2>(eb_result);

    assert(shrunken_means.size() == K);
    assert(shrinkage >= 0.0 && shrinkage <= 1.0);

    double grand_mean = 0.0;
    for (double rm : raw_means) grand_mean += rm;
    grand_mean /= static_cast<double>(raw_means.size());

    for (std::size_t i = 0; i < K; ++i) {
        double dist_raw = std::fabs(raw_means[i] - grand_mean);
        double dist_shrunken = std::fabs(shrunken_means[i] - grand_mean);
        assert(dist_shrunken <= dist_raw + 1e-12);
    }

    int reps = 400;
    int wins = 0;
    double tot_raw = 0.0, tot_shr = 0.0;
    for (int r = 0; r < reps; ++r) {
        auto rep_result = empirical_bayes_shrinkage(PY_REP_GROUPS[r]);
        const auto& shr = std::get<0>(rep_result);
        const auto& raw = std::get<1>(rep_result);
        double se_raw = 0.0, se_shr = 0.0;
        for (std::size_t i = 0; i < K; ++i) {
            double d = raw[i] - TRUE_MEANS[i];
            se_raw += d * d;
            d = shr[i] - TRUE_MEANS[i];
            se_shr += d * d;
        }
        tot_raw += se_raw;
        tot_shr += se_shr;
        if (se_shr < se_raw) ++wins;
    }

    std::cout << "replications: " << reps << " mean SE raw " << (tot_raw / reps)
              << " vs shrunken " << (tot_shr / reps)
              << " shrinkage wins " << (static_cast<double>(wins) / reps) << "\n";

    assert(tot_shr < tot_raw);
    assert(static_cast<double>(wins) / reps > 0.55);
    assert(shrinkage >= 0.0);

    auto unif_result = empirical_bayes_shrinkage(PY_UNIFORM_GROUPS);
    double shrink_unif = std::get<2>(unif_result);

    std::cout << "own-weight: heterogeneous " << shrinkage << " vs homogeneous " << shrink_unif << "\n";
    assert(shrink_unif < shrinkage - 0.1);

    std::cout << "PASS\n";
    return 0;
}